"""Tests for the real-fog-data pipeline (offline, deterministic). Uses ONLY synthetic data generated by the project:
these tests prove the code paths work and recover known parameters, NOT that the physics matches reality."""
import os, sys, tempfile, json
import numpy as np
import pandas as pd
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from falcon_eye.fog import FOG_SCENARIOS, FogScenario, LayeredFogScenario, angstrom_exponent
from falcon_eye.fogdata import (parse_metar_visibility, find_rvr, load_visibility_csv, load_metar_file,
                                FogCalibration, FogProfile, SM_M)
from falcon_eye.sensor import FalconEyeSensor
from falcon_eye.replay import (load_measurements, load_truth, replay_files, ReplayConfig, run_replay, score)
from falcon_eye.calibrate import estimate_sensor_statistics, fit_fog_calibration, fit_extinction_scale
from falcon_eye.synthetic_data import generate_dataset
from falcon_eye.simulation import SimulationConfig, run_scenario, make_head_on_scenario

fails = 0
def check(name, cond):
    global fails
    print(("PASS: " if cond else "FAIL: ") + name); fails += (not cond)
def raises(fn, exc=ValueError):
    try: fn()
    except exc: return True
    except Exception: return False
    return False
close = lambda a, b, tol=1e-6: abs(a - b) <= tol

# ---------------- METAR / RVR parsing ----------------
P = lambda s: parse_metar_visibility(s)
o = P("METAR XXXX 050300Z 00000KT 0800 FG VV002 05/05 Q1020"); check("ICAO 0800 -> 800 m exact", o.meters == 800 and o.qualifier == "exact")
o = P("XXXX 050600Z 02005KT 9999 FEW030 09/06 Q1022"); check("ICAO 9999 -> 10 km LOWER BOUND (not a measurement)", o.meters == 10000 and o.qualifier == "greater_than")
o = P("XXXX 050600Z 02005KT CAVOK 09/06 Q1022"); check("CAVOK -> 10 km, qualifier cavok", o.meters == 10000 and o.qualifier == "cavok")
o = P("XXXX 050600Z 02005KT 0000 FG"); check("ICAO 0000 means < 50 m", o.meters < 50 and o.qualifier == "less_than")
o = P("XXXX 050600Z 27010KT 240V300 4000 RA"); check("variable-wind group skipped before visibility", o.meters == 4000)
o = P("XXXX 050600Z 27010KT 1200NE BR"); check("directional suffix accepted (1200NE -> 1200 m)", o.meters == 1200)
o = P("KXXX 050700Z 18005KT 1 1/2SM BR OVC004"); check("US '1 1/2SM' -> 1.5 SM", close(o.meters, 1.5 * SM_M, 1e-3))
o = P("KXXX 050700Z 18005KT 10SM CLR"); check("US 10SM -> 16093 m", close(o.meters, 10 * SM_M, 1e-3))
o = P("KXXX 050700Z 18005KT P6SM FEW050"); check("US P6SM -> lower bound", o.qualifier == "greater_than" and close(o.meters, 6 * SM_M, 1e-3))
o = P("KXXX 050700Z 18005KT M1/4SM FG"); check("US M1/4SM -> less-than 1/4 SM", o.qualifier == "less_than" and close(o.meters, 0.25 * SM_M, 1e-3))
o = P("KXXX 050700Z 18005KT 1/2SM FG"); check("US 1/2SM -> 0.5 SM", close(o.meters, 0.5 * SM_M, 1e-3))
check("no visibility group -> None (never invented)", P("XXXX 050300Z 00000KT //// FG") is None)
check("bare '0800' accepted", P("0800").meters == 800)
check("time group 050300Z not mistaken for visibility", P("XXXX 050300Z").meters if P("XXXX 050300Z") else True)
r = find_rvr("XXXX 050400Z 00000KT 0350 FG R28L/1200V1800FT R10/P2000N")
check("RVR parsed, feet converted", len(r) == 2 and close(r[0]["rvr_m"], 1200 * 0.3048, 1e-6) and close(r[0]["rvr_variable_to_m"], 1800 * 0.3048, 1e-6))
check("RVR P2000 = greater_than, trend N", r[1]["qualifier"] == "greater_than" and r[1]["trend"] == "N")
check("RVR is NOT returned as visibility", P("XXXX 050400Z 00000KT 0350 FG R28L/0400").meters == 350)

# ---------------- CSV loading + QC ----------------
tmp = tempfile.mkdtemp()
def wcsv(name, text):
    p = os.path.join(tmp, name); open(p, "w").write(text); return p
s = load_visibility_csv(wcsv("a.csv", "time_s,visibility_km\n0,10\n60,2\n120,0.5\n"))
check("unit taken from header (km) and converted", list(s.vis_m) == [10000, 2000, 500])
check("unit NOT stated -> refuses to guess", raises(lambda: load_visibility_csv(wcsv("b.csv", "time_s,visibility\n0,10\n60,2\n"))))
s = load_visibility_csv(wcsv("c.csv", "time_s,visibility\n0,1\n60,0.5\n"), unit="sm"); check("explicit statute-mile unit", close(s.vis_m[0], SM_M, 1e-3))
s = load_visibility_csv(wcsv("d.csv", "time_s,visibility_m\n0,5000\n10,-9999\n20,abc\n30,-3\n40,4000\n50,4000\n40,4100\n60,3000\n"))
q = s.qc; check("sentinel/NaN/negative dropped and counted", q["n_dropped_missing_or_sentinel"] == 2 and q["n_dropped_nonpositive"] == 1)
check("out-of-order rows sorted, duplicates resolved (last kept)", q["n_duplicate_times"] == 1 and np.all(np.diff(s.t_s) > 0) and 4100.0 in s.vis_m)
s = load_visibility_csv(wcsv("e.csv", "time_s,visibility_m\n0,9999\n10,15000\n20,30000\n"))
check("only the 9999/10000 cap is a lower bound; 15 km sensor reading is a measurement", list(s.lower_bound) == [True, False, False])
s = load_visibility_csv(wcsv("f.csv", "timestamp,mor_m\n2024-01-05T06:00:00Z,3000\n2024-01-05T06:01:00Z,2500\n"))
check("ISO timestamps parsed, rebased to first sample", list(s.t_s) == [0.0, 60.0])
check("single valid row -> error", raises(lambda: load_visibility_csv(wcsv("g.csv", "time_s,visibility_m\n0,5000\n"))))
check("log-linear interpolation (1 km -> 10 km, midpoint = 3162 m)", close(FogProfile.from_schedule([(0, 1000), (10, 10000)]).visibility_at(5.0), 3162.2777, 1e-3))
ms = load_metar_file(os.path.join(tmp, "m.txt")) if False else None
from falcon_eye.synthetic_data import METAR_SAMPLE
mp = wcsv("m.txt", METAR_SAMPLE); ms = load_metar_file(mp)
check("METAR file: 9 observations, hourly spacing", len(ms) == 9 and close(ms.t_s[1] - ms.t_s[0], 3600))
check("METAR file: CAVOK / 9999 / P6SM flagged as lower bounds", int(ms.lower_bound.sum()) == 3)
check("METAR file: US 1 1/2SM converted", any(close(v, 1.5 * SM_M, 1e-3) for v in ms.vis_m))

# ---------------- calibration object + fog physics ----------------
cal = FogCalibration()
ok = True
for k, f in FOG_SCENARIOS.items():
    sc = cal.scenario_for(f.visibility_m)
    ok &= close(sc.noise_multiplier, f.noise_multiplier) and close(sc.false_return_multiplier, f.false_return_multiplier)
check("default calibration reproduces the 4 built-in fog anchors exactly", ok)
nms = [cal.scenario_for(v).noise_multiplier for v in (50, 100, 300, 500, 1000, 2000, 5000, 20000, 50000)]
check("noise multiplier monotonic non-increasing in visibility", all(a >= b - 1e-12 for a, b in zip(nms, nms[1:])))
cp = os.path.join(tmp, "cal.json"); FogCalibration(noise_multiplier=(4, 2, 1.3, 1), source="t").to_json(cp)
check("calibration JSON round trip", FogCalibration.from_json(cp).noise_multiplier == (4, 2, 1.3, 1))
f550 = FogScenario("x", 2000, 1.5, 1.8, extinction_model="kim")
check("wavelength model is a no-op at 550 nm and for 'koschmieder'",
      close(f550.two_way_transmittance(800, 550), FogScenario("x", 2000, 1.5, 1.8).two_way_transmittance(800)))
check("905 nm sees further than 550 nm in light fog (Kim)", f550.two_way_transmittance(1000, 905) > 2 * f550.two_way_transmittance(1000, 550))
check("Kim q = 0 below 500 m visibility (dense fog ~ wavelength independent)", angstrom_exponent(0.1, "kim") == 0.0
      and close(FogScenario("d", 100, 5, 8, extinction_model="kim").two_way_transmittance(50, 905), FogScenario("d", 100, 5, 8).two_way_transmittance(50)))
L = LayeredFogScenario("bank", 20000, 1, 1, layers=((2000, 3000, 100),))
check("layered fog transmittance equals the analytic path integral",
      close(np.log(L.two_way_transmittance(4000)), -2 * (3.912 / 20000 * 3000 + 3.912 / 100 * 1000), 1e-9))
check("a target in front of the fog bank is unaffected by it", close(L.two_way_transmittance(1500), FogScenario("c", 20000, 1, 1).two_way_transmittance(1500)))
check("unknown extinction model rejected", raises(lambda: angstrom_exponent(1.0, "foo")))
n_a = n_b = 0
for sd in range(3):
    sa = FalconEyeSensor(rng=np.random.default_rng(sd)); sb = FalconEyeSensor(rng=np.random.default_rng(sd), wavelength_nm=905.0)
    for _ in range(3000):
        n_a += sa.measure(1000, 0.0, 100.0, f550).target_detected; n_b += sb.measure(1000, 0.0, 100.0, f550).target_detected
check(f"sensor wavelength option increases detections in light fog ({n_b} vs {n_a})", n_b > 2 * n_a)
check("sensor default wavelength is None (legacy behaviour)", FalconEyeSensor().wavelength_nm is None)

# ---------------- simulation with a time-varying profile ----------------
host, tgt = make_head_on_scenario(initial_range_m=6000, closing_speed_mps=100)
base = SimulationConfig(duration_s=60, dt_s=0.1, fog_key="clear", mode="lidar", seed=5)
r0 = run_scenario(host, tgt, base)
host, tgt = make_head_on_scenario(initial_range_m=6000, closing_speed_mps=100)
r1 = run_scenario(host, tgt, SimulationConfig(duration_s=60, dt_s=0.1, fog_key="clear", mode="lidar", seed=5,
                                              fog_profile=FogProfile.from_schedule([(0, 20000), (60, 20000)])))
check("constant 20 km profile == static 'clear' scenario (identical arrays)",
      np.array_equal(r0.tracked_range, r1.tracked_range, equal_nan=True) and r0.warning_time == r1.warning_time)
host, tgt = make_head_on_scenario(initial_range_m=3000, closing_speed_mps=20)
r2 = run_scenario(host, tgt, SimulationConfig(duration_s=60, dt_s=0.1, fog_key="clear", mode="lidar", seed=5,
                  fog_profile=FogProfile.from_schedule([(0, 20000), (30, 20000), (45, 200), (60, 100)])))
true_det = r2.detected & ~r2.false_detection          # genuine detections only (false returns rise in fog)
n = len(true_det); early = int(true_det[: n // 3].sum()); late = int(true_det[2 * n // 3:].sum())
check(f"fog deteriorating over time reduces GENUINE LiDAR detections ({early} early vs {late} late)", early > 5 * max(late, 1))
fl = int(r2.false_detection[2 * n // 3:].sum()); fe = int(r2.false_detection[: n // 3].sum())
check(f"...while false returns increase in the thick fog ({fe} early vs {fl} late)", fl > fe)

# ---------------- replay on synthetic data ----------------
d1 = os.path.join(tmp, "syn1"); P1 = generate_dataset(d1, n_episodes=8, seed=11)
res = replay_files(P1["measurements"], P1["truth"], P1["visibility"])
ov = res["scores"]["overall"]
check("replay runs end-to-end and scores against truth", ov["n_ticks"] > 1000 and ov["availability"] > 0.5)
check("replay range error is sane (< 25 m RMSE) and no ghost tracks", ov["range_rmse_m"] < 25 and ov["ghost_track_frac"] < 0.02)
check("replay reports per-visibility-band scores", len(res["scores"]["by_visibility"]) >= 3)
check("no false warnings relative to truth", ov.get("false_warning_frac", 0.0) < 0.05)
check("synthetic files are stamped SYNTHETIC", all(open(P1[k]).readline().startswith("# SYNTHETIC") for k in ("measurements", "truth", "visibility")))
P2 = generate_dataset(os.path.join(tmp, "syn2"), n_episodes=8, seed=11, include_sigma=False)
res2 = replay_files(P2["measurements"], P2["truth"], P2["visibility"])
check("log WITHOUT sigma columns still replays (confidence-weighted fusion fallback)", res2["scores"]["overall"]["availability"] > 0.5)
res3 = replay_files(P2["measurements"], P2["truth"], P2["visibility"], cfg=ReplayConfig(default_sigma={"lidar": (3.0, 0.005, 1.0), "radar": (15.0, 0.026, 2.0)}))
check("default_sigma supplies missing sigmas (inverse-variance fusion on a sigma-less log)", res3["scores"]["overall"]["range_rmse_m"] is not None)
P3 = generate_dataset(os.path.join(tmp, "syn3"), n_episodes=8, seed=11, dirty=True)
res4 = replay_files(P3["measurements"], P3["truth"], P3["visibility"])
q4 = res4["qc"]
check("corrupted log: invalid/duplicate/out-of-order rows detected and COUNTED", q4["measurements"]["n_dropped_invalid_detections"] > 0
      and q4["measurements"]["n_duplicate_rows"] > 0 and q4["measurements"]["n_out_of_order"] > 0)
check("corrupted visibility file: sentinels counted", q4["visibility"]["n_dropped_missing_or_sentinel"] > 0)
check("corrupted log still replays with comparable accuracy", res4["scores"]["overall"]["range_rmse_m"] < 25)
bad = os.path.join(tmp, "bad.csv"); open(bad, "w").write("time_s,sensor,detected,range_m,angle_rad,closing_speed_mps\n0,lidar,1,100,0,10\n0,sonar,1,100,0,10\n")
check("unknown sensor name rejected", raises(lambda: load_measurements(bad)))
open(bad, "w").write("time_s,sensor,detected\n0,lidar,1\n"); check("missing columns rejected with a clear error", raises(lambda: load_measurements(bad)))
open(bad, "w").write("time_s,sensor,detected,range_m,angle_deg,range_rate_mps\n0,lidar,1,1000,3,-50\n0.1,lidar,1,995,3,-50\n")
mm, _ = load_measurements(bad); check("angle_deg and range_rate_mps (negative=closing) converted", close(mm["angle_rad"][0], np.radians(3)) and mm["closing_speed_mps"][0] == 50)

# ---------------- calibration recovery (closed loop on synthetic data) ----------------
world = FogCalibration(noise_multiplier=(4.0, 2.0, 1.3, 1.0), false_return_multiplier=(6.0, 3.0, 1.5, 1.0), extinction_scale=0.6)
Pw = generate_dataset(os.path.join(tmp, "world"), n_episodes=60, seed=3, world=world)
meas, _ = load_measurements(Pw["measurements"]); tr, _ = load_truth(Pw["truth"]); vis = load_visibility_csv(Pw["visibility"])
fit = fit_extinction_scale(meas, tr, vis, "lidar")
check(f"extinction scale recovered: k={fit['k_best']:.3f} (true 0.6), 95% interval {fit['k_ci95'][0]:.3f}-{fit['k_ci95'][1]:.3f}",
      abs(fit["k_best"] - 0.6) < 0.06 and fit["k_ci95"][0] <= 0.6 <= fit["k_ci95"][1])
check("clear-air detection probability recovered (p0 ~ 0.98)", abs(fit["p0_best"] - 0.98) < 0.05)
st = estimate_sensor_statistics(meas, tr, vis, "lidar")
check("contamination by false returns is estimated per band (thin-detection bands flagged)", st["contamination"].max() > 0.5)
cal2 = fit_fog_calibration(st)
ok = True
for v, nm in zip(cal2.visibility_m, cal2.noise_multiplier):
    t = world.scenario_for(v).noise_multiplier / world.scenario_for(cal2.visibility_m[-1]).noise_multiplier
    ok &= abs(nm - t) / t < 0.25
check("fitted noise multipliers within 25% of the generating world (usable bands)", ok)
check("contaminated bands are skipped (and the report says so), never extrapolated", "0-200" in cal2.source and len(cal2.visibility_m) >= 2)
single = generate_dataset(os.path.join(tmp, "single"), n_episodes=3, seed=4, vis_range_m=(15000, 20000))
m1, _ = load_measurements(single["measurements"]); t1, _ = load_truth(single["truth"]); v1 = load_visibility_csv(single["visibility"])
check("only one usable visibility band -> refuses to fit (no extrapolation)", raises(lambda: fit_fog_calibration(estimate_sensor_statistics(m1, t1, v1, "lidar"))))
w905 = FogCalibration(noise_multiplier=(4.0, 2.0, 1.3, 1.0), extinction_model="kim", wavelength_nm=905.0)
Pk = generate_dataset(os.path.join(tmp, "kim"), n_episodes=60, seed=5, world=w905, lidar_wavelength_nm=905.0)
mk, _ = load_measurements(Pk["measurements"]); tk, _ = load_truth(Pk["truth"]); vk = load_visibility_csv(Pk["visibility"])
fk = fit_extinction_scale(mk, tk, vk, "lidar", wavelength_nm=905.0, extinction_model="kim")
fw = fit_extinction_scale(mk, tk, vk, "lidar")
check(f"905 nm data: Kim model explains it (k={fk['k_best']:.2f}, CI contains 1.0)", fk["k_ci95"][0] <= 1.0 <= fk["k_ci95"][1])
check(f"wrong (Koschmieder) model is detectably wrong on the same data (k={fw['k_best']:.2f}, CI excludes 1.0)", not (fw["k_ci95"][0] <= 1.0 <= fw["k_ci95"][1]))

print("\n" + ("All real-data pipeline tests passed." if not fails else f"{fails} test(s) FAILED."))
sys.exit(1 if fails else 0)
